{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLS enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket public access block for api_docs bucket does not have block_public_acls enabled, potentially allowing public ACLs to be applied."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket public access block for api_docs bucket does not have block_public_policy enabled, potentially allowing public policies to be applied."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Ensure S3 bucket has ignore public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket public access block for api_docs bucket does not have ignore_public_acls enabled, potentially allowing public ACLs to be considered."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Ensure S3 bucket has 'restrict_public_buckets' enabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket public access block for api_docs bucket has restrict_public_buckets set to false, potentially allowing public access to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n  block_public_acls   = true\n  block_public_policy = true\n  ignore_public_acls  = true\n  restrict_public_buckets = true\n}",
  "fix_summary": "Enabled block_public_acls, block_public_policy, ignore_public_acls, and restrict_public_buckets on the aws_s3_bucket_public_access_block.api_docs resource to prevent public access to the S3 bucket."
}
